package limits_test

import (
	"errors"
	"strings"
	"testing"

	"github.com/mbashem/cftracker/backend/internal/limits"
)

// Generated by Codex and not thoroughly checked for correctness.
func TestNormalizeListNameEnforcesUnicodeLengthAfterTrimming(t *testing.T) {
	for _, testCase := range []struct {
		name, input, want string
		invalid           bool
	}{
		{"trims surrounding whitespace", "  Contest  ", "Contest", false},
		{"accepts exactly 100 Unicode characters", " " + strings.Repeat("界", limits.ListNameCharacters) + " ", strings.Repeat("界", limits.ListNameCharacters), false},
		{"rejects 101 Unicode characters", strings.Repeat("界", limits.ListNameCharacters+1), "", true},
		{"rejects empty names", "", "", true},
		{"rejects whitespace names", " \n\t", "", true},
		{"rejects invalid UTF8", string([]byte{255}), "", true},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			actual, err := limits.NormalizeListName(testCase.input)
			if actual != testCase.want || errors.Is(err, limits.ErrInvalidListName) != testCase.invalid {
				t.Fatalf("name=%q error=%v", actual, err)
			}
		})
	}
}
